(() => {
 const PAGE_SIZE=18,rawCache=new Map(),inflight=new Map();
 let catalog=[],catalogData,filter={query:'',kind:'all',category:'',level:'',sort:'curated',page:1},current=null,detailMarkdown='',detailBase='',detailValues={},detailToken=0,observer;
 let favorites=new Set();try{favorites=new Set(JSON.parse(localStorage.getItem('readme-studio-favorites')||'[]'));}catch{}
 const builtins=templates.map(t=>({...t,id:'starter-'+t.id,builtin:t.id,type:'design',sourceId:'studio',category:'Guided starters',kind:'builder',difficulty:'Basic',tags:['Guided starters'],description:t.desc}));
 const esc=escapeHTML;
 function saveFavorites(){try{localStorage.setItem('readme-studio-favorites',JSON.stringify([...favorites]));}catch{}$('saved-count').textContent=favorites.size;}
 function toggleFavorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);saveFavorites();renderCards();if(current?.id===id)syncDetailFavorite();}
 function syncDetailFavorite(){$('detail-save').textContent=favorites.has(current.id)?'♥ Saved to collection':'♡ Save for later';}
 function selectedItems(){return catalog.filter(t=>(filter.kind==='all'||filter.kind==='saved'&&favorites.has(t.id)||t.type===filter.kind)&&(!filter.category||t.category===filter.category||t.tags?.includes(filter.category))&&(!filter.level||t.difficulty===filter.level)&&(!filter.query||[t.name,t.username,t.description,t.category,...(t.tags||[])].join(' ').toLowerCase().includes(filter.query))).sort((a,b)=>filter.sort==='az'?a.name.localeCompare(b.name):filter.sort==='za'?b.name.localeCompare(a.name):0);}
 function card(t){
  const art=t.builtin?`<div class="template-art ${t.style}"><div class="art-title">${esc(t.title)}</div><div class="art-sub">Developer. Maker. Curious human.</div><div class="art-line"></div><div class="art-line" style="width:60%"></div><div class="art-badges"><i></i><i></i><i></i></div></div>`:t.type==='design'?`<div class="gallery-art"><img src="${esc(t.thumbnail)}" alt="${esc(t.name)} design preview" loading="lazy"></div>`:`<div class="community-art" data-mini="${esc(t.id)}"><div class="community-art-fallback"><span>▤</span><strong>${esc(t.name)}</strong><small>Original community README</small><div class="art-line"></div><div class="art-line" style="width:60%"></div></div></div>`;
  return `<article class="gallery-card"><button class="favorite-button ${favorites.has(t.id)?'is-saved':''}" aria-label="${favorites.has(t.id)?'Unsave':'Save'} ${esc(t.name)}" aria-pressed="${favorites.has(t.id)}" data-favorite="${esc(t.id)}">${favorites.has(t.id)?'♥':'♡'}</button><button class="gallery-card-art" data-open-template="${esc(t.id)}" aria-label="Preview ${esc(t.name)}">${art}</button><div class="gallery-card-content"><div class="card-eyebrow"><span>${esc(t.category)}</span><span>${t.builtin?'GUIDED':t.type==='design'?t.kind.toUpperCase():'EXAMPLE'}</span></div><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><div class="card-meta"><span>${esc(t.type==='community'?'Community profile':t.difficulty)}</span><span>${t.type==='community'?'↗ Original author':t.sourceId==='studio'?'✧ README Studio':'◈ Furkan Beydemir'}</span></div><button class="card-open" data-open-template="${esc(t.id)}">${t.builtin?'Customize template':t.type==='design'?'Preview & customize':'Preview README'} <span>↗</span></button></div></article>`;
 }
 function renderCards(){
  if(!catalog.length)return;const matches=selectedItems(),pagesCount=Math.max(1,Math.ceil(matches.length/PAGE_SIZE));filter.page=Math.min(filter.page,pagesCount);
  const start=(filter.page-1)*PAGE_SIZE,items=matches.slice(start,start+PAGE_SIZE);
  $('catalog-results').textContent=matches.length?`${start+1}–${Math.min(start+PAGE_SIZE,matches.length)} of ${matches.length} ${filter.kind==='saved'?'saved ideas':'templates & profiles'}`:'No matching profiles. Try another style or clear your search.';
  $('template-grid').innerHTML=items.length?items.map(card).join(''):`<div class="gallery-empty"><span>✧</span><h3>${filter.kind==='saved'?'Your inspiration shelf starts here.':'A different direction, perhaps?'}</h3><p>${filter.kind==='saved'?'Tap the heart on a template to keep it here.':'Try another search or reset the filters.'}</p></div>`;
  $('template-grid').querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>toggleFavorite(b.dataset.favorite));
  $('template-grid').querySelectorAll('[data-open-template]').forEach(b=>b.onclick=()=>openTemplate(b.dataset.openTemplate));
  const pageNumbers=new Set([1,pagesCount,filter.page-1,filter.page,filter.page+1]);let last=0,buttons='';
  for(const n of [...pageNumbers].filter(n=>n>0&&n<=pagesCount).sort((a,b)=>a-b)){if(n-last>1)buttons+='<span>…</span>';buttons+=`<button data-page-number="${n}" class="${n===filter.page?'active':''}" aria-label="Page ${n}" ${n===filter.page?'aria-current="page"':''}>${n}</button>`;last=n;}
  $('gallery-pagination').innerHTML=pagesCount>1?`<button data-page-number="${filter.page-1}" ${filter.page===1?'disabled':''}>← Previous</button><div>${buttons}</div><button data-page-number="${filter.page+1}" ${filter.page===pagesCount?'disabled':''}>Next →</button>`:'';
  $('gallery-pagination').querySelectorAll('button').forEach(b=>b.onclick=()=>{filter.page=Number(b.dataset.pageNumber);renderCards();$('templates-page').scrollIntoView({behavior:'smooth',block:'start'});});
  observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){observer.unobserve(e.target);enqueuePreview(e.target);}},{rootMargin:'80px'});
  document.querySelectorAll('[data-mini]').forEach(el=>observer.observe(el));
 }
 let miniRunning=0,miniQueue=[];
 function enqueuePreview(el){miniQueue.push(el);runMiniQueue();}
 function runMiniQueue(){while(miniRunning<4&&miniQueue.length){const el=miniQueue.shift();if(!el.isConnected)continue;miniRunning++;miniPreview(el).finally(()=>{miniRunning--;runMiniQueue();});}}
 async function miniPreview(el){const t=catalog.find(x=>x.id===el.dataset.mini);try{const result=await loadReadme(t);if(!el.isConnected)return;const content=document.createElement('div');content.className='community-mini-document';content.inert=true;content.setAttribute('aria-hidden','true');content.innerHTML=studioRender(result.markdown.slice(0,18000),{sourceBase:result.base});for(const a of content.querySelectorAll('a'))a.replaceWith(...a.childNodes);for(const img of content.querySelectorAll('img'))img.loading='lazy';el.replaceChildren(content);el.classList.add('loaded');}catch{/* The creator and source remain available if a preview is unavailable. */}}
 async function loadReadme(t){
  if(rawCache.has(t.id))return rawCache.get(t.id);if(inflight.has(t.id))return inflight.get(t.id);
  const promise=(async()=>{let lastError;for(const url of t.rawCandidates||[]){try{const response=await fetch(url,{signal:AbortSignal.timeout(12000),referrerPolicy:'no-referrer'});if(!response.ok)throw Error('HTTP '+response.status);const markdown=await response.text();if(markdown.length>250000)throw Error('This README is too large for the editor.');const base=t.archiveSource||t.sourceId==='community-templates'?`https://raw.githubusercontent.com/${t.username}/${t.username}/HEAD/`:new URL('.',url).href;const result={markdown,base};rawCache.set(t.id,result);return result;}catch(e){lastError=e;}}throw lastError||Error('README unavailable');})();
  inflight.set(t.id,promise);try{return await promise;}finally{inflight.delete(t.id);}
 }
 function placeholderDefinition(t,key){return t.placeholders?.find(p=>p.token===key||p.token.includes('*')&&new RegExp('^'+p.token.replace('*','.+')+'$').test(key));}
 function initialValue(key,t){const p=placeholderDefinition(t,key);const values={name:state.name,username:state.username,tagline:state.headline,role:state.headline,bio_paragraph:state.bio,currently_line:state.working,currently_one:state.working,learning_focus:state.learning,website:state.website?.replace(/^https?:\/\//,''),website_url:state.website?(/^https?:\/\//.test(state.website)?state.website:'https://'+state.website):'',email:state.email,skills_csv:state.tech.join(', ')};return values[key]||p?.example||'';}
 function renderTemplateFields(t){
  const tokens=[...new Set([...t.sample.matchAll(/(?<!\$)\{\{([a-zA-Z0-9_]+)\}\}/g)].map(m=>m[1]))];detailValues={};
  $('template-fields').innerHTML=tokens.length?'<h3>Make it yours</h3>'+tokens.map((key,i)=>{detailValues[key]=initialValue(key,t);const label=key.replaceAll('_',' ');return `<label>${esc(label)}<input data-placeholder-index="${i}" aria-label="Template ${esc(label)}" value="${esc(detailValues[key])}"></label>`;}).join(''):'';
  $('template-fields').querySelectorAll('input').forEach(input=>input.oninput=()=>{detailValues[tokens[+input.dataset.placeholderIndex]]=input.value;refreshDetail();});
 }
 function interpolate(sample,values){return sample.replace(/(?<!\$)\{\{([a-zA-Z0-9_]+)\}\}/g,(whole,key)=>Object.hasOwn(values,key)?values[key]:whole);}
 function refreshedMarkdown(){return current.type==='design'?interpolate(current.sample,detailValues):detailMarkdown;}
 function refreshDetail(){const md=refreshedMarkdown();$('detail-code').value=md;$('detail-preview').innerHTML=studioRender(md,{sourceBase:detailBase,previewAsset:current.type==='design'?new URL(current.thumbnail,location.href).href:''});}
 async function openTemplate(id){
  const t=catalog.find(x=>x.id===id);if(!t)return;
  if(t.builtin){state.sourceMode=false;state.sourceBase='';state.previewAsset='';state.template=t.builtin;if(t.builtin==='midnight')state.sections.stats=true;if(t.builtin==='open-source')state.sections.repos=true;if(t.builtin==='minimal'){state.sections.stats=false;state.sections.streak=false;state.sections.languages=false;}populate();navigate('builder');toast('Starter applied. Your profile details are here.');return;}
  const token=++detailToken;current=t;detailMarkdown='';detailBase='';detailValues={};$('detail-title').textContent=t.name;$('detail-category').textContent=t.category;$('detail-description').textContent=t.description;$('detail-source').href=t.source;$('detail-meta').innerHTML=`<span>${esc(t.type==='design'?t.kind.toUpperCase():'COMMUNITY EXAMPLE')}</span><span>${esc(t.difficulty)}</span>`;$('detail-preview').replaceChildren();$('detail-code').value='';$('template-fields').replaceChildren();$('use-community-template').disabled=true;$('detail-loading').textContent='';syncDetailFavorite();
  document.querySelector('[data-detail-view="preview"]').click();
  $('detail-attribution').textContent=t.type==='design'?'Design by Furkan Beydemir · MIT license. Source and license are included in bundle exports.':'Original community example. Its author details and links are preserved; edit them before publishing. Check the original source for reuse terms.';
  $('detail-setup').textContent=t.type==='design'?(t.kind==='action'?'Requires GitHub Actions setup. The bundle includes the original setup guide. Generated images appear after the workflow runs.':t.kind==='svg'?'Includes a self-hosted SVG. Export the bundle to get the image and setup guide. Edit SVG text labels inside the asset.':'Customize the fields below, then open the Markdown in your editor.'):'Live README preview from the linked source. External images and badges depend on their original hosts.';
  $('template-dialog').showModal();
  if(t.type==='design'){renderTemplateFields(t);detailBase=new URL('.',location.href).href;refreshDetail();$('use-community-template').disabled=false;}
  else { $('detail-loading').textContent='Fetching the original README…';try{const result=await loadReadme(t);if(token!==detailToken)return;detailMarkdown=result.markdown;detailBase=result.base;refreshDetail();$('detail-loading').textContent='';$('use-community-template').disabled=false;}catch{if(token!==detailToken)return;$('detail-loading').innerHTML='This README could not be loaded. The source may have moved, or the network may be unavailable. <button class="text-button" id="retry-readme">Try again ↻</button>';$('retry-readme').onclick=()=>{$('template-dialog').close();openTemplate(id);};} }
 }
 function closeDetail(){detailToken++;$('template-dialog').close();}
 $('close-template-dialog').onclick=closeDetail;$('template-dialog').addEventListener('cancel',()=>detailToken++);
 document.querySelectorAll('[data-detail-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-detail-view]').forEach(x=>x.classList.toggle('active',x===b));$('detail-preview').hidden=b.dataset.detailView!=='preview';$('detail-code').hidden=b.dataset.detailView!=='code';});
 $('detail-save').onclick=()=>toggleFavorite(current.id);
 function absoluteCommunityMarkdown(md,base){const resolve=url=>{if(/^(?:[a-z]+:|#|\{\{)/i.test(url))return url;try{return new URL(url,base).href;}catch{return url;}};return md.replace(/\]\(([^\s)]+)([^)]*)\)/g,(_,url,tail)=>`](${resolve(url)}${tail})`).replace(/\b(src|href)=(['"])(.*?)\2/gi,(_,attr,q,url)=>`${attr}=${q}${resolve(url)}${q}`);}
 $('use-community-template').onclick=()=>{
  state.sourceMode=true;state.sourceName=current.name;state.sourceId=current.id;state.sourceType=current.type;state.sourceKind=current.kind;state.sourceLink=current.source;state.sourceBase=detailBase;state.previewAsset=current.type==='design'?new URL(current.thumbnail,location.href).href:'';state.sourceValues={...detailValues};state.sourceMarkdown=current.type==='design'?refreshedMarkdown():absoluteCommunityMarkdown(detailMarkdown,detailBase);closeDetail();populate();navigate('builder');syncStudioSource();toast('Template opened. Make the story your own.');
 };
 window.syncStudioSource=function(){
  const source=!!state.sourceMode;
  document.querySelectorAll('.editor-tab').forEach(b=>{if(b.dataset.tab==='source')b.hidden=!source;else b.hidden=source;});
  $('guided-mode-button').hidden=!source;$('bundle-button').hidden=!(source&&state.sourceType==='design');
  if(source){document.querySelectorAll('.tab-content').forEach(el=>el.hidden=el.id!=='source-tab');document.querySelectorAll('.editor-tab').forEach(b=>{b.classList.toggle('active',b.dataset.tab==='source');b.setAttribute('aria-selected',String(b.dataset.tab==='source'));});$('source-editor-title').textContent=state.sourceName;$('source-original').href=state.sourceLink;$('source-editor-note').textContent=state.sourceType==='community'?'This original example includes its author’s details. Edit the Markdown, links, and images to make it yours.':'Your template is ready to edit. Changes appear instantly in the live preview.';if(document.activeElement!==$('source-editor'))$('source-editor').value=state.sourceMarkdown||'';$('source-bundle-note').textContent=state.sourceType==='design'?(state.sourceKind==='action'?'Export the ZIP for the original GitHub Actions setup guide. A README alone will not generate the dynamic image.':'Export the ZIP to include the SVG asset, original setup guide, and license. SVG text labels are edited in the asset file.'):'Original source and author attribution are available above.';$('current-template').textContent=state.sourceName;}
  else if(!$('source-tab').hidden){$('source-tab').hidden=true;document.querySelector('[data-tab="details"]').click();}
 };
 $('source-editor').addEventListener('input',e=>{state.sourceMarkdown=e.target.value;update();});
 $('guided-mode-button').onclick=()=>{state.sourceMode=false;state.sourceBase='';state.previewAsset='';populate();toast('Back to your guided profile. Your imported details are here.');};
 $('bundle-button').onclick=async()=>{
  const t=catalog.find(t=>t.id===state.sourceId);if(!t||t.type!=='design')return;const button=$('bundle-button');button.disabled=true;button.textContent='Preparing bundle…';
  try{const [svg,guide,license]=await Promise.all([fetch(t.thumbnail).then(r=>{if(!r.ok)throw Error('Asset unavailable');return r.text();}),fetch('design-guides/'+t.slug+'.md').then(r=>{if(!r.ok)throw Error('Guide unavailable');return r.text();}),fetch('licenses/design-led-MIT.txt').then(r=>{if(!r.ok)throw Error('License unavailable');return r.text();})]);const zip=new JSZip();zip.file('README.md',markdown());zip.file('assets/'+t.slug+'.svg',svg);zip.file('SETUP.md',`# ${t.name}\n\nOriginal source: ${t.source}\n\nThe SVG asset retains the original example text. Edit its text labels before uploading. For Action templates, follow the workflow setup below before expecting generated images.\n\n---\n\n`+guide);zip.file('LICENSE-template.txt',license);const blob=await zip.generateAsync({type:'blob'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=t.slug+'-profile.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Bundle ready: README, SVG, setup guide, and license.');}catch{toast('Could not prepare the bundle. Please try again.');}finally{button.disabled=false;button.textContent='↓ Export bundle (.zip)';}
 };
 function refreshFilters(){filter.page=1;renderCards();}
 $('catalog-search').oninput=e=>{filter.query=e.target.value.trim().toLowerCase();refreshFilters();};$('catalog-sort').onchange=e=>{filter.sort=e.target.value;refreshFilters();};$('catalog-level').onchange=e=>{filter.level=e.target.value;refreshFilters();};
 document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{filter.kind=b.dataset.kind;document.querySelectorAll('[data-kind]').forEach(x=>x.classList.toggle('active',x===b));refreshFilters();});
 function setCategory(category){filter.category=category;$('catalog-category').value=category;document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));refreshFilters();}
 $('reset-filters').onclick=()=>{filter={query:'',kind:'all',category:'',level:'',sort:'curated',page:1};$('catalog-search').value='';$('catalog-level').value='';$('catalog-sort').value='curated';document.querySelectorAll('[data-kind]').forEach(b=>b.classList.toggle('active',b.dataset.kind==='all'));setCategory('');};
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!$('templates-page').hidden){e.preventDefault();e.stopImmediatePropagation();$('catalog-search').focus();}},true);
 async function init(){
  try {const response=await fetch('data/catalog.json');if(!response.ok)throw Error('Catalog unavailable');catalogData=await response.json();if(!Array.isArray(catalogData.items))throw Error('Invalid catalog');catalog=[...catalogData.items.slice(0,catalogData.counts.designs),...builtins,...catalogData.items.slice(catalogData.counts.designs)];$('catalog-error').hidden=true;$('catalog-total').textContent=catalog.length;$('all-count').textContent=catalog.length;$('design-count').textContent=catalog.filter(t=>t.type==='design').length;$('community-count').textContent=catalog.filter(t=>t.type==='community').length;saveFavorites();
   const categories=[...new Set(catalog.map(t=>t.category))].sort();$('category-filters').innerHTML=['','Minimal','Animated','Themed','Gamified','Community'].map(c=>`<button data-category="${c}" class="${c?'':'active'}">${c||'All styles'}</button>`).join('')+`<select id="catalog-category" aria-label="All template categories"><option value="">All categories</option>${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select>`;$('category-filters').querySelectorAll('button').forEach(b=>b.onclick=()=>setCategory(b.dataset.category));$('catalog-category').onchange=e=>setCategory(e.target.value);
   $('catalog-snapshot').textContent=`${catalogData.counts.total} sourced entries + ${builtins.length} Studio starters · Snapshot ${new Date(catalogData.generatedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}`;
   pages.templates[1]='Your next profile <em>starts here.</em>';pages.templates[2]=`${catalog.length} templates and community profiles. Find your style, preview the README, and make it yours.`;renderCards();syncStudioSource();update();if(location.hash==='#templates')navigate('templates');
  }catch(e){$('catalog-error').hidden=false;$('catalog-error').innerHTML='<p>The collection could not be loaded. Please run the app with <code>npm start</code> and try again.</p><button id="retry-catalog" class="secondary-button">Reload collection ↻</button>';$('retry-catalog').onclick=init;$('catalog-results').textContent='Collection unavailable';}
 }
 init();
})();
